  function updateWingman(dt) {
    if (!wingmanDrone) return;
    const cfg = GAME_STATE.aiConfig;
    if (wingmanDrone.hp <= 0) {
      spawnExplosionParticles(wingmanDrone.position, 61695, 20, 16);
      sfx("explode");
      scene.remove(wingmanDrone.mesh);
      wingmanDrone = null;
      showFloatText("WINGMAN DOWN", "#ff5533");
      return;
    }
    wingmanDrone.hitFlash = Math.max(0, wingmanDrone.hitFlash - dt * 3);
    if (wingmanDrone.hitFlash <= 0.01) restoreHitFlash(wingmanDrone.mesh);
    let target = null, best = Infinity;
    const desired = cfg.preset === "defensive" ? 14 : cfg.preset === "sniper" ? 55 : 26;
    enemyEntities.forEach((e) => {
      const d = wingmanDrone.position.distanceTo(e.position);
      if (d < best) {
        best = d;
        target = e;
      }
    });
    let moveTarget;
    if (GAME_STATE.wingmanHold) {
      moveTarget = playerEntity.position.clone().add(new Vector3(0, 5, 0));
    } else if (target && best < desired * 1.6) {
      const away = wingmanDrone.position.clone().sub(target.position).normalize();
      moveTarget = target.position.clone().add(away.multiplyScalar(desired * 0.9)).setY(5.5);
      moveTarget.y = 5.5;
    } else {
      moveTarget = playerEntity.position.clone().add(new Vector3(Math.sin(clock.elapsedTime * 0.8) * 6, 5.5, 4 + Math.cos(clock.elapsedTime * 0.8) * 6));
    }
    moveTarget.x = MathUtils.clamp(moveTarget.x, -140, 140);
    moveTarget.z = MathUtils.clamp(moveTarget.z, -140, 140);
    const toT = moveTarget.clone().sub(wingmanDrone.position);
    wingmanDrone.velocity.lerp(toT.multiplyScalar(0.9), Math.min(1, dt * 3.2));
    wingmanDrone.velocity.clampLength(0, cfg.preset === "sniper" ? 26 : 34);
    wingmanDrone.position.addScaledVector(wingmanDrone.velocity, dt);
    wingmanDrone.mesh.position.copy(wingmanDrone.position);
    wingmanDrone.mesh.visible = !firstPersonView;
    if (target) wingmanDrone.mesh.lookAt(target.position.x, 3, target.position.z);
    wingmanDrone.ring.rotation.z += dt * 4;
    wingmanDrone.fireCooldown -= dt;
    if (target && best < (cfg.preset === "sniper" ? 70 : 48) && wingmanDrone.fireCooldown <= 0) {
      wingmanDrone.fireCooldown = cfg.preset === "berserker" ? 0.22 : cfg.preset === "sniper" ? 0.9 : 0.45;
      const dir = target.position.clone().add(new Vector3(0, 2.5, 0)).sub(wingmanDrone.position).normalize();
      spawnProjectile({ pos: wingmanDrone.position.clone(), dir, speed: 150, isPlayer: true, damage: 70, life: 1.6, color: 61695, size: 0.22, trail: true });
      if (wingmanDrone.position.distanceTo(camera.position) < 60) sfx("plasma");
    }
  }
  function enemyFireAtPlayer(enemy, shots) {
    const barrelTips = [];
    enemy.mesh.traverse((child) => {
      if (child.name === "barrelTip") {
        const wp = new Vector3();
        child.getWorldPosition(wp);
        barrelTips.push(wp);
      }
    });
    const spawnPoints = barrelTips.length > 0 ? barrelTips : [enemy.position.clone().add(new Vector3(0, 3, 0))];
    const aim = playerEntity.position.clone().add(new Vector3(0, 1.8, 0));
    spawnPoints.forEach((sp) => {
      const spread = enemy.isBoss ? 0.02 : 0.05;
      const fireDir = aim.clone().sub(sp).normalize();
      fireDir.x += (Math.random() - 0.5) * spread;
      fireDir.y += (Math.random() - 0.5) * spread * 0.5;
      fireDir.z += (Math.random() - 0.5) * spread;
      spawnProjectile({
        pos: sp.clone(),
        dir: fireDir,
        speed: enemy.isBoss ? 105 : 95,
        isPlayer: false,
        damage: enemy.damage,
        life: 2.6,
        color: enemy.isBoss ? 16724804 : 16720452,
        size: enemy.isBoss ? 0.6 : 0.38,
        trail: true
      });
    });
    if (enemy.position.distanceTo(camera.position) < 80) sfx("cannon");
  }
  function updateBossLogic(boss, delta, dist) {
    const hpFrac = boss.hp / boss.maxHp;
    const newPhase = hpFrac <= 0.33 ? 3 : hpFrac <= 0.66 ? 2 : 1;
    if (newPhase !== boss.phase) {
      boss.phase = newPhase;
      showFloatText(`\u26A0 ${boss.name} \u2014 PHASE ${newPhase}`, "#ff2244");
      sfx("bigexplode");
      cameraShake = Math.max(cameraShake, 0.8);
      spawnExplosionParticles(boss.position.clone().setY(6), 16729088, 30, 26);
    }
    boss.attackTimer -= delta;
    if (boss.attackTimer <= 0 && dist < 110) {
      const shots = boss.phase === 1 ? 2 : boss.phase === 2 ? 3 : 4;
      boss.attackTimer = boss.phase === 3 ? 1 : boss.phase === 2 ? 1.3 : 1.7;
      for (let s = 0; s < shots; s++) {
        setTimeout(() => {
          if (GAME_STATE.inBattle && boss.hp > 0) enemyFireAtPlayer(boss, 1);
        }, s * 120);
      }
    }
    boss.missileVolleyTimer -= delta;
    if (boss.missileVolleyTimer <= 0 && dist < 130) {
      boss.missileVolleyTimer = boss.phase === 3 ? 3.2 : 5;
      const missiles = boss.phase === 1 ? 5 : 8;
      showFloatText("MISSILE VOLLEY INBOUND", "#ff6600");
      for (let m = 0; m < missiles; m++) {
        setTimeout(() => {
          if (!GAME_STATE.inBattle || boss.hp <= 0) return;
          const sp = boss.position.clone().add(new Vector3((Math.random() - 0.5) * 8, 7 + boss.scale, (Math.random() - 0.5) * 8));
          const aim = playerEntity.position.clone().add(new Vector3((Math.random() - 0.5) * 10, 1.5, (Math.random() - 0.5) * 10)).sub(sp).normalize();
          spawnProjectile({ pos: sp, dir: aim, speed: 70, isPlayer: false, damage: boss.damage * 0.55, life: 3.2, color: 16742144, size: 0.5, trail: true });
          sfx("rail");
        }, m * 140);
      }
    }
    if (boss.phase >= 2) {
      boss.shockwaveTimer -= delta;
      if (boss.shockwaveTimer <= 0) {
        boss.shockwaveTimer = 8;
        showFloatText("SHOCKWAVE \u2014 DASH AWAY!", "#ff2244");
        const ring = new Mesh(
          new RingGeometry(1, 2.2, 40),
          new MeshBasicMaterial({ color: 16729088, transparent: true, opacity: 0.9, side: DoubleSide })
        );
        ring.rotation.x = -Math.PI / 2;
        ring.position.set(boss.position.x, 0.4, boss.position.z);
        scene.add(ring);
        particles.push({ mesh: ring, ring: true, vel: new Vector3(), life: 0.9, maxLife: 0.9, ringGrow: 26 });
        setTimeout(() => {
          if (!GAME_STATE.inBattle) return;
          sfx("bigexplode");
          cameraShake = Math.max(cameraShake, 0.9);
          spawnExplosionParticles(boss.position.clone().setY(1), 16733440, 24, 20);
          explosionDamage(boss.position.clone(), 16, 320, true);
        }, 900);
      }
    }
  }
  function updateBossVisuals(delta) {
    enemyEntities.forEach((e) => {
      if (!e.isBoss) return;
      const t = clock.elapsedTime;
      e.mesh.position.y = Math.sin(t * 1.4) * 0.5;
      const eyeColor = e.phase === 3 ? 16711935 : e.phase === 2 ? 16737792 : 16720452;
      e.mesh.traverse((o) => {
        const m = o;
        const mat = m.material;
        if (m.isMesh && mat && mat.emissive && !o.userData.baseEmissive) {
          mat.emissiveIntensity = Math.max(mat.emissiveIntensity, 0.4 + e.phase * 0.35);
        }
      });
    });
  }
