      if (shot.trailAges[i] >= 900) continue;
      shot.trailAges[i] += delta;
      const f = Math.max(0, 1 - shot.trailAges[i] / 0.42);
      const ff = f * f;
      shot.trailColors[i * 3] = 0.52 * ff;
      shot.trailColors[i * 3 + 1] = 0.12 * ff;
      shot.trailColors[i * 3 + 2] = 1 * ff;
